import{_ as o,o as u,c as e,ag as a}from"./chunks/framework.DaAXJYxM.js";const d=JSON.parse('{"title":"第76章 请假","description":"","frontmatter":{},"headers":[],"relativePath":"第76章_请假.md","filePath":"第76章_请假.md"}'),q={name:"第76章_请假.md"};function p(_,t,r,n,s,c){return u(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="第76章-请假" tabindex="-1">第76章 请假 <a class="header-anchor" href="#第76章-请假" aria-label="Permalink to &quot;第76章 请假&quot;">​</a></h1><p>十月十四号，她跟我说她要请假。她说，我阿婆中风了。我说，严重吗。她说，现在在 ICU 外面，还没进去，人叫不醒。我说，那你怎么办。她说，我买票。我说，你这边不是不能回。她说，我回。我说，你那实习。她说，我请两周。我说，你请两周他们不留你。她那边隔了一会儿。她说，那就不留。我说，我买哪一班。她说，我买哪一班你别管钱。我说，你别管钱。她说，我知道。我说，你知道什么。她说，你说&quot;你别管钱&quot;的时候，你是在说你现在管不了。我自己算过了。一万二。我卡上有九千，剩下的我找何叶借。</p><p>我看到&quot;找何叶借&quot;这一句，心里很不是滋味。因为我知道她这个人一辈子不借钱。高一她跟我说过一句：我这辈子开口跟人要钱只有一次，那次我难受了一个月。现在她第二次开口，是为了回去看一个不认识她的人。</p><p>那天下午她一直没上线。六点她发了一张机场的照片。她说，我提早三个小时到。我不敢回宿舍，我一回去我就想我不去了。我说，你去吧。她说，你讲这句话讲得这么轻。我说，我讲重了你要改主意？她说，我不会改。我就是听不得你说&quot;去吧&quot;。你说&quot;去吧&quot;这两个字，我就想到我妈。我妈那年跟我说&quot;你去吧&quot;，是让我去念那个我不念的专业。我现在一听见&quot;去吧&quot;我就想，我又在让一个人走。我说，那我说什么。她说，你说&quot;我在这儿&quot;。我坐在那儿。我说，我在这儿。她发了一个很难看的表情。她说，行了。我登机了。</p><p>她在路上的那二十个小时，我一条也没发。不是我不想发。是因为我算了一下：我这边发的每一条，她那边落地以后是一堆她没回的消息。而她那边现在没有心情还这一堆。我这边夜里三点，她那边应该是傍晚。我在床上躺着听呼噜。</p><p>第二天她上线是十月十六号，她那边下午四点。她说，我到了。我说，见到人了？她说，见到了。我在 ICU 外面站着，隔一层玻璃。她不睁眼。我在那个玻璃前面站了很久。我说，她认得你吗。她隔了很久。这一句她隔的时间，比&quot;我阿婆中风了&quot;那一句还长。然后她说。昨天下午医生让她睁一次眼。她睁了一下。我妈把我推前面，我妈说，妈，谁回来了。阿婆看我。她看了我十秒钟。她讲了一句话。我说，讲的什么。她说，她说，你怎么这么瘦。我看到这一句，坐在椅子上，半天动不了。她说，她不认得我。她喊的是我妈那一辈的人，她那天盯着我看了十秒，说的是&quot;你怎么这么瘦&quot;。可是她那一句，是我这一辈子听过的最准的一句。她脑子里现在没有我这个人。她的身体记得我瘦。我从八岁到十六岁，她每年给我两百。她是从她那个铁盒子里拿的，她不敢当面给，她给我都是在我走的时候塞我书包侧袋。我那八百块我一分没花。</p><p>我说，那你去哪儿都带着？她说，我上大学带着。我那三年在高中旁边租的那个单间，第一个月的押金就是她从那个盒子里拿的五百。我妈不知道。我妈那时候不给我钱，我妈说你要什么你说，但是我们不能惯你。阿婆给的时候什么都不问。她给我钱那天她只说一句，她说&quot;你买点你爱吃的&quot;。我这一辈子只有一个人给我东西是不问我有没有用的。就是她。现在我一年能挣她那个盒子的三十倍。她躺在那儿，她不认得钱，也不认得我。</p><p>我那天下午没去实验室。我给我妈打了一个电话，我说我们家那个铁盒子还在不在。我妈说在，你要干什么。我说，我看看。我妈说，你要钱你说话。我说，我不要钱。我就想知道奶奶那个盒子里现在还放着什么。我妈停了一下。我妈说，放着你的出生证明，你小时候一颗牙，还有几块钱。我说，几块。我妈说，六块。她说，你奶奶就留着那六块，我给她钱她都存着。我那天夜里在宿舍，把这两件事摆在一起算。她那边的六块，她这边的一万二。一个人给一个人留六块钱，另一个人给另一个人花一万二回来看一张不认识她的脸。我算出来我心里那股东西叫什么。我不愿意写出来。因为写出来它就更丑。我说的是：我在算她为了一个不认得她的人花了一万二，而她跟我说过两次&quot;机票太贵了今年回不去&quot;。</p><p>第三天她上线，跟我说的第一句是——她说，我今天在机场丢了一个包。里面有一支笔，两本笔记，还有一个充电头。那个充电头我这辈子买了三个都坏，我今天丢了第四个我居然不难受。我说，那笔重要吗。她说，那笔是我妹给我塞进行李箱的。她说，她说姐你带着这个写字好看。我说，那你回去买一支一模一样的。她说，买不到，那个笔是三块钱一支的。我说，我明天就飞回去了。她说，你那两周。我说，我请了十六天。我说，超过两周他们就不留了。她说，我知道。我说，那你明年作品集——她说，闻迟。你今天怎么这么爱算。我说，我在帮你算。她说，你帮我把这笔算清楚了吗。我说，哪笔。她说，我这一趟花的那笔。我告诉你，我不算。我要是算我就不来了。我来这一次我什么都没了，可是我看见她说我瘦了。我明年再挣，我后年再挣，我挣到能带她出来那一天。她说，她那天说的&quot;你怎么这么瘦&quot;，我要让她以后天天能说出这句。她说，她说得出这句就说明她还在。</p><p>我看完了。我说，好。她说，你别&quot;好&quot;。你现在这个&quot;好&quot;，是你把话收起来了。我说，我是觉得你说得对。她说，你说得不对。你觉得我这次做的事，跟你想的那件事不一样。我说，没有。她说，你有。你从我说一万二开始就变了，你后来问我&quot;你请两周他们不留你&quot;的时候，你其实是在看我值不值。我不值。你算不清我这一趟。你算得清我就不给你算了。我那天没有再回。她那晚十一点二十下线。</p><p>第二天她上线，第一条是：我那个室友把我那盆绿萝浇死了。我回来一看，土是稀的。我说我养了两年。她说，她说她不知道。我说，那你再买一盆。她说，我不想买。我今天不想再买任何东西。</p>',11)])])}const l=o(q,[["render",p]]);export{d as __pageData,l as default};
